/* BRRPATCH: patches the DOS game's RACING.EXE in place (see brrpatch.h).
 *
 * brrdata.h (generated by "brr.py brrpatch-build") lists the steps that rebuild the
 * patched RACING.EXE from the player's own: copy N bytes from offset X of their file, or
 * write N bytes of ours. The input and the result are both checked by size and SHA-256.
 * The patched file is written as RACING.NEW first; only when it's exactly right is
 * RACING.EXE renamed to RACING.ORI and RACING.NEW to RACING.EXE. */
#include <stdio.h>
#include <string.h>
#include <stdint.h>
#include "brrpatch.h"
#include "sha256.h"
#include "brrdata.h"

#if defined(__DOS__) || defined(__NT__) || defined(_WIN32)
#define SEPARATOR "\\"
#else
#define SEPARATOR "/"
#endif
#define PATH_SIZE 260
#define CHUNK 2048

static uint8_t buffer[CHUNK];

void (*brr_dos_progress)(void);

static void progress(void)
{
    static unsigned chunks;
    if (brr_dos_progress && ++chunks % (65536U / CHUNK) == 0)
        brr_dos_progress();
}

const char *brr_dos_version(void) { return BRR_PATCH_VERSION; }
const char *brr_dos_tag(void) { return BRR_PATCH_TAG; }

static void join(char *out, const char *folder, const char *name)
{
    size_t n = strlen(folder);
    out[0] = 0;
    if (n + strlen(name) + 2 > PATH_SIZE)
        return;
    strcpy(out, folder);
    if (n && folder[n - 1] != '\\' && folder[n - 1] != '/' && folder[n - 1] != ':')
        strcat(out, SEPARATOR);
    strcat(out, name);
}

static void say(char *message, unsigned size, const char *text)
{
    strncpy(message, text, size - 1);
    message[size - 1] = 0;
}

static int matches(struct brr_sha256_state *s, const char *expected)
{
    uint8_t digest[32];
    char hex[65];
    brr_sha256_final(s, digest);
    brr_sha256_hex(digest, hex);
    return !strcmp(hex, expected);
}

static int file_state(const char *path)
{
    struct brr_sha256_state s;
    uint32_t total = 0;
    size_t got;
    int failed;
    FILE *f = path[0] ? fopen(path, "rb") : NULL;
    if (!f)
        return BRR_DOS_MISSING;
    brr_sha256_init(&s);
    while ((got = fread(buffer, 1, CHUNK, f)) > 0) {
        brr_sha256_update(&s, buffer, got);
        total += (uint32_t)got;
        progress();
    }
    failed = ferror(f);
    fclose(f);
    if (failed)
        return BRR_DOS_UNREADABLE;
    if (total == BRR_ORIGINAL_SIZE)
        return matches(&s, BRR_ORIGINAL_SHA256) ? BRR_DOS_ORIGINAL : BRR_DOS_OTHER;
    if (total == BRR_PATCHED_SIZE)
        return matches(&s, BRR_PATCHED_SHA256) ? BRR_DOS_PATCHED : BRR_DOS_OTHER;
    return BRR_DOS_OTHER;
}

int brr_dos_state(const char *folder)
{
    char path[PATH_SIZE];
    join(path, folder, "RACING.EXE");
    return file_state(path);
}

static int put(FILE *out, struct brr_sha256_state *s, const uint8_t *data, size_t size)
{
    brr_sha256_update(s, data, size);
    progress();
    return fwrite(data, 1, size, out) == size;
}

/* RACING.NEW from the original RACING.EXE; 1 when it's exactly the patched file */
static int write_patched(const char *source, const char *target)
{
    struct brr_sha256_state s;
    uint32_t literal = 0, written = 0;
    unsigned i;
    int ok = 1;
    FILE *in = fopen(source, "rb"), *out;
    if (!in)
        return 0;
    out = fopen(target, "wb");
    if (!out) {
        fclose(in);
        return 0;
    }
    brr_sha256_init(&s);
    for (i = 0; ok && i < BRR_OP_COUNT; i++) {
        uint32_t from = BRR_OPS[i][0], left = BRR_OPS[i][1];
        written += left;
        if (from == BRR_LITERAL) {
            while (ok && left) {
                size_t n = left > CHUNK ? CHUNK : (size_t)left;
                ok = put(out, &s, BRR_LITERALS + literal, n);
                literal += n;
                left -= n;
            }
        } else {
            ok = fseek(in, (long)from, SEEK_SET) == 0;
            while (ok && left) {
                size_t n = left > CHUNK ? CHUNK : (size_t)left;
                ok = fread(buffer, 1, n, in) == n && put(out, &s, buffer, n);
                left -= n;
            }
        }
    }
    fclose(in);
    if (fclose(out) != 0)
        ok = 0;
    return ok && written == BRR_PATCHED_SIZE && matches(&s, BRR_PATCHED_SHA256);
}

int brr_dos_patch(const char *folder, char *message, unsigned size)
{
    char exe[PATH_SIZE], backup[PATH_SIZE], fresh[PATH_SIZE], text[600];
    int state, kept;
    join(exe, folder, "RACING.EXE");
    join(backup, folder, "RACING.ORI");
    join(fresh, folder, "RACING.NEW");
    state = file_state(exe);
    if (state == BRR_DOS_MISSING) {
        sprintf(text, "Can't find RACING.EXE in %s. Run the patch in the game's folder (for example "
                "C:\\BIGRED), or give the folder.", folder[0] ? folder : "this folder");
        say(message, size, text);
        return -1;
    }
    if (state == BRR_DOS_PATCHED) {
        say(message, size, "RACING.EXE is already patched. Nothing was changed.");
        return 1;
    }
    if (state == BRR_DOS_UNREADABLE) {
        say(message, size, "Couldn't read RACING.EXE. Nothing was changed.");
        return -1;
    }
    if (state == BRR_DOS_OTHER) {
        say(message, size, "This RACING.EXE isn't the one the patch is for: it needs RACING.EXE "
            "v2.24 (629,472 bytes), from the official v2.25 update. Nothing was changed.");
        return -1;
    }
    kept = file_state(backup);
    if (kept != BRR_DOS_MISSING && kept != BRR_DOS_ORIGINAL) {
        say(message, size, "RACING.ORI is already there, and it isn't the original RACING.EXE. Move "
            "or rename it, then try again. Nothing was changed.");
        return -1;
    }
    if (!write_patched(exe, fresh)) {
        remove(fresh);
        say(message, size, "Couldn't write the patched file (RACING.NEW). Is the disk full or "
            "write-protected? The patch needs about 650 KB free. Nothing was changed.");
        return -1;
    }
    /* RACING.ORI may already hold the original, from an earlier patch and undo */
    if (kept == BRR_DOS_ORIGINAL ? remove(exe) != 0 : rename(exe, backup) != 0) {
        remove(fresh);
        say(message, size, "Couldn't rename RACING.EXE to RACING.ORI (is it read-only?). "
            "Nothing was changed.");
        return -1;
    }
    if (rename(fresh, exe) != 0) {
        rename(backup, exe);
        remove(fresh);
        say(message, size, "Couldn't rename RACING.NEW to RACING.EXE. The original RACING.EXE is "
            "back in place.");
        return -1;
    }
    sprintf(text, "Patched RACING.EXE (%s). The original is saved as RACING.ORI.", BRR_PATCH_TAG);
    say(message, size, text);
    return 0;
}

int brr_dos_restore(const char *folder, char *message, unsigned size)
{
    char exe[PATH_SIZE], backup[PATH_SIZE];
    int state, kept;
    join(exe, folder, "RACING.EXE");
    join(backup, folder, "RACING.ORI");
    kept = file_state(backup);
    state = file_state(exe);
    if (state == BRR_DOS_ORIGINAL) {
        say(message, size, "RACING.EXE is already the original. Nothing was changed.");
        return 1;
    }
    if (kept == BRR_DOS_MISSING) {
        say(message, size, "There's no RACING.ORI (the saved original) here to put back. "
            "Nothing was changed.");
        return -1;
    }
    if (kept != BRR_DOS_ORIGINAL) {
        say(message, size, "RACING.ORI isn't the original RACING.EXE, so it wasn't put back. "
            "Nothing was changed.");
        return -1;
    }
    if (state != BRR_DOS_PATCHED && state != BRR_DOS_MISSING) {
        say(message, size, "RACING.EXE has been changed by something other than this patch, so it "
            "wasn't replaced. To put the original back anyway, delete RACING.EXE and rename "
            "RACING.ORI to RACING.EXE. Nothing was changed.");
        return -1;
    }
    if (state == BRR_DOS_PATCHED && remove(exe) != 0) {
        say(message, size, "Couldn't replace RACING.EXE (is it read-only?). Nothing was changed.");
        return -1;
    }
    if (rename(backup, exe) != 0) {
        say(message, size, "The patched RACING.EXE was removed, but RACING.ORI couldn't be renamed. "
            "Rename RACING.ORI to RACING.EXE yourself.");
        return -1;
    }
    say(message, size, "The original RACING.EXE is back in place.");
    return 0;
}
